#!/usr/bin/env python3
"""
fh6_setup.py - the whole toolkit in one file.

    python3 fh6_setup.py

Writes every tool into ~/fh6, creates the virtual environment, installs the
two dependencies, and runs the tests. One download instead of thirteen, which
also means the versions cannot drift apart - every file here came from the
same build.

Nothing is downloaded and nothing runs from the network; the tools are
embedded below as compressed text.
"""

import base64
import os
import subprocess
import sys
import zlib

DEST = os.path.join(os.path.expanduser("~"), "fh6")
VENV = os.path.join(DEST, "venv")
DEPS = ("sounddevice", "numpy")

FILES = {
    "fh6_draggy.py": "",
    "fh6_reaction.py": "",
    "fh6_slip.py": "",
    "fh6_launch.py": "",
    "fh6_shift.py": "",
    "fh6_tune.py": "",
    "fh6_audio_probe.py": "",
    "fh6_audio_map.py": "",
    "phone_mic_test.py": "",
    "udp_probe.py": "",
    "fh6_test.py": "",
    "fh6_web.py": "",
    "fh6_install.py": "",
    "fh6_strip.py": "",
    "fh6_merge.py": "",
    "fh6_verify.py": "",
    "fh6_cars.py": ""
}


def main():
    os.makedirs(DEST, exist_ok=True)
    print(f"\n  writing {len(FILES)} tools to {DEST}\n")
    for name, blob in sorted(FILES.items()):
        data = zlib.decompress(base64.b64decode(blob))
        path = os.path.join(DEST, name)
        old = b""
        if os.path.exists(path):
            with open(path, "rb") as f:
                old = f.read()
        with open(path, "wb") as f:
            f.write(data)
        print(f"    {name:<22}{'unchanged' if old == data else 'written'}")

    py = (os.path.join(VENV, "Scripts", "python.exe") if os.name == "nt"
          else os.path.join(VENV, "bin", "python3"))
    if not os.path.exists(py):
        print("\n  creating virtual environment...")
        r = subprocess.run([sys.executable, "-m", "venv", VENV],
                           capture_output=True, text=True)
        if r.returncode != 0:
            print("  could not create it:", r.stderr.strip()[:200])
            return 1
    missing = [d for d in DEPS
               if subprocess.run([py, "-c", f"import {d}"],
                                 capture_output=True).returncode != 0]
    if missing:
        print(f"  installing {', '.join(missing)}...")
        r = subprocess.run([py, "-m", "pip", "install", "-q", *missing],
                           capture_output=True, text=True)
        if r.returncode != 0:
            err = (r.stderr or r.stdout).strip()
            print("  pip failed:", err[:300])
            if "portaudio" in err.lower():
                print("  try:  brew install portaudio   then run this again")

    print("\n  running tests...\n")
    r = subprocess.run([py, os.path.join(DEST, "fh6_test.py")],
                       cwd=DEST, capture_output=True, text=True)
    tail = [l for l in r.stdout.splitlines() if "passed" in l or "FAIL" in l]
    for line in tail:
        print("   ", line.strip())

    print("\n  Ready. To use:\n")
    print("    cd ~/fh6")
    exe = "venv\\Scripts\\python" if os.name == "nt" else "venv/bin/python3"
    print(f"    {exe} fh6_reaction.py       # measure runs")
    print(f"    {exe} fh6_web.py            # browse them")
    if os.name == "nt":
        print(f"    {exe} fh6_reaction.py --loopback   # PC: capture game audio")
    print()
    return 0


if __name__ == "__main__":
    sys.exit(main())
